  {
    // Compute the “forward” distance r = n mod k
    let r: i8 = n % k;
    // Since 0 ≤ n and 1 ≤ k, the standard signed‐remainder satisfies 0 ≤ r < k
    assert(r >= 0 && r < k);

    // Compute the “backward” distance dr = k – r
    let dr: i8 = k - r;
    // From 0 ≤ r < k and k ≥ 1 we get 1 ≤ dr ≤ k
    assert(dr > 0 && dr <= k);

    // Return whichever is smaller
    if r <= dr {
      result = r;
    } else {
      result = dr;
    }
  }

